SELECT event_type, substr(ts,1,10) d, COUNT(*) FROM strategy_events WHERE event_type IN ('TWAP_STRIKE_CROSS','TMINUS_CHECKPOINT','TWAP_PROJECTED_SIDE_CHANGE','SETTLEMENT_PATH_THRESHOLD_CROSS','MARKET_OPENING_TWAP_SAMPLE','MARKET_TWAP_SUMMARY','RESEARCH_STORAGE_GUARD_TRIGGERED') AND ts>='2026-10-01' GROUP BY 1,2 ORDER BY 1,2;
